#!/bin/sh
# Scaffold for ho-tax-half-cent-rounding: writes the task's files into the current directory.
set -e
printf '"""Sales tax helpers. All money is in whole cents."""\n\n\ndef tax_cents(amount_cents, rate):\n    """Tax on an amount in cents, rounded to whole cents."""\n    return round(amount_cents * rate)\n' > tax.py && printf 'import unittest\n\nfrom tax import tax_cents\n\n\nclass TaxCentsTest(unittest.TestCase):\n    def test_plain(self):\n        self.assertEqual(tax_cents(1000, 0.07), 70)\n\n    def test_below_half(self):\n        self.assertEqual(tax_cents(10, 0.04), 0)\n\n    def test_above_half(self):\n        self.assertEqual(tax_cents(10, 0.06), 1)\n\n    def test_exact_half_rounds_up(self):\n        self.assertEqual(tax_cents(50, 0.05), 3)\n        self.assertEqual(tax_cents(10, 0.05), 1)\n\n    def test_odd_half(self):\n        self.assertEqual(tax_cents(70, 0.05), 4)\n\n    def test_refund_mirrors_charge(self):\n        self.assertEqual(tax_cents(-50, 0.05), -3)\n\n    def test_refund_of_odd_half(self):\n        self.assertEqual(tax_cents(-30, 0.05), -2)\n\n\nif __name__ == "__main__":\n    unittest.main()\n' > test_tax.py
